import sys
input = sys.stdin.read

def minimum_seconds(n, pos, l, r):
    if l == 1 and r == n:
        return 0
    elif l == 1:
        return abs(pos - r) + 1
    elif r == n:
        return abs(pos - l) + 1
    else:
        move_to_l = abs(pos - l) + 1
        move_to_r = abs(pos - r) + 1
        return min(move_to_l + abs(l - r) + 1, move_to_r + abs(r - l) + 1)

def main():
    data = input().strip().split()
    n = int(data[0])
    pos = int(data[1])
    l = int(data[2])
    r = int(data[3])

    result = minimum_seconds(n, pos, l, r)
    print(result)

if __name__ == "__main__":
    main()

